/* ==========================================
   TOTAL SQUARE MODE — STYLUS
   Force sharp corners across every website
   ========================================== */

/* 1. NUKE ALL BORDER RADIUS */
*,
*::before,
*::after,
*::first-letter,
*::first-line {
    border-radius: 0 !important;
}

/* 2. OVERRIDE RADIUS VARIABLES */
:root,
:host {
    --radius: 0px !important;
    --radius-xs: 0px !important;
    --radius-sm: 0px !important;
    --radius-md: 0px !important;
    --radius-lg: 0px !important;
    --radius-xl: 0px !important;
    --radius-2xl: 0px !important;
    --radius-3xl: 0px !important;
    --rounded: 0px !important;
    --rounded-sm: 0px !important;
    --rounded-md: 0px !important;
    --rounded-lg: 0px !important;
    --rounded-xl: 0px !important;
    --rounded-full: 0px !important;
    --chakra-radii-full: 0px !important;
    --chakra-radii-md: 0px !important;
    --chakra-radii-lg: 0px !important;
    --bs-border-radius: 0px !important;
    --bs-border-radius-sm: 0px !important;
    --bs-border-radius-lg: 0px !important;
    --bs-border-radius-xl: 0px !important;
    --bs-border-radius-xxl: 0px !important;
    --bs-border-radius-pill: 0px !important;
}

/* 3. BUTTONS — NO PILLS */
button,
[role="button"],
input[type="button"],
input[type="submit"],
input[type="reset"],
.btn,
.button,
a.button {
    border-radius: 0 !important;
}

/* 4. INPUTS, SEARCH BARS & TEXT AREAS */
input,
textarea,
select,
option,
[role="textbox"],
[role="combobox"],
[contenteditable="true"] {
    border-radius: 0 !important;
}

/* 5. CARDS, PANELS & CONTAINERS */
.card,
[class*="card"],
[class*="panel"],
[class*="modal"],
[class*="dialog"],
[class*="popover"],
[class*="tooltip"],
[class*="dropdown"],
[class*="sheet"],
[class*="drawer"] {
    border-radius: 0 !important;
}

/* 6. IMAGES, AVATARS & THUMBNAILS */
img,
picture,
video,
canvas,
iframe,
.avatar,
[class*="avatar"],
[class*="thumbnail"],
[class*="image-wrapper"],
[class*="img-wrapper"] {
    border-radius: 0 !important;
}

/* 7. NAVIGATION & MENUS */
nav,
header,
[role="navigation"],
[role="menu"],
[role="menuitem"],
[role="tab"],
[role="tablist"] {
    border-radius: 0 !important;
}

/* 8. TAGS, CHIPS & BADGES */
.badge,
.tag,
.chip,
.pill,
[class*="badge"],
[class*="chip"],
[class*="tag"] {
    border-radius: 0 !important;
}

/* 9. PROGRESS BARS & SLIDERS */
progress,
meter,
input[type="range"],
[role="progressbar"],
[role="slider"] {
    border-radius: 0 !important;
}

/* 10. REMOVE CLIPPING USED TO CREATE ROUNDED SHAPES */
[style*="border-radius"],
[style*="borderRadius"] {
    border-radius: 0 !important;
}

/* 11. FORCE SHARP OUTLINES */
*:focus,
*:focus-visible {
    border-radius: 0 !important;
}

/* 12. STOP TRANSFORMS FROM HIDING SIMPLE CORNERS */
button,
input,
select,
textarea {
    -webkit-appearance: auto;
    appearance: auto;
    border-radius: 0 !important;
}
